func _init() -> void:
	var scene = load("res://scenes/Player.tscn")
	var player = scene.instantiate()
	root.add_child(player)

	var anim_tree: AnimationTree = player.get_node("AnimationTree")
	var controller = player.get_node("PlayerAnimController")

	print("anim_player: ", anim_tree.anim_player)
	print("tree_root type: ", anim_tree.tree_root.get_class())

	# Transitions
	var sm = anim_tree.tree_root
	var found = false
	for t in sm.transitions:
		var from = sm.node_get_name(t.from_node)
		var to = sm.node_get_name(t.to_node)
		if from == "Locomotion" and to == "Attack":
			print("L->A cond: ", t.advance_condition)
			found = true
		if from == "Attack" and to == "Locomotion":
			print("A->L switch mode: ", t.switch_mode)

	# Test API
	controller.set_move_input(Vector2(0.5, 0.5))
	print("blend_position: ", anim_tree.get("parameters/Locomotion/blend_position"))

	controller.trigger_attack()
	print("condition_attack: ", anim_tree.get("parameters/conditions/condition_attack"))

	# Playback - wait a frame
	#await process_frame

	quit()

